using namespace std;

const long long MOD = 1000000007LL;

// 快速倍增返回 pair<F_n, F_{n+1}>
pair<long long, long long> fastFib(long long n) {
    if (n == 0) return {0, 1};
    auto p = fastFib(n >> 1);
    long long a = p.first, b = p.second;
    long long c = (a * ((2 * b % MOD - a + MOD) % MOD)) % MOD;
    long long d = (a * a % MOD + b * b % MOD) % MOD;
    if (n & 1)
        return {d, (c + d) % MOD};
    else
        return {c, d};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        string s;
        long long n;
        cin >> s >> n;

        long long L0 = s.size();
        long long B0 = 0;
        for (char c : s)
            if (c == '1') B0++;
        long long L1 = L0 + B0;

        if (n == 0) {
            cout << L0 % MOD << '\n';
            continue;
        }

        auto [fn, fnPlus1] = fastFib(n);
        long long fnMinus1 = (fnPlus1 - fn + MOD) % MOD;

        long long ans;
        if (n == 1) {
            ans = L1 % MOD;
        } else {
            ans = ((L1 % MOD) * fn % MOD + (L0 % MOD) * fnMinus1 % MOD) % MOD;
        }
        cout << ans << '\n';
    }
    return 0;
}
